```cpp
    // Define CGAL types for arrangement
    typedef CGAL::Exact_predicates_exact_constructions_kernel Kernel;
    typedef Kernel::Point_2                                     Point_2;
    typedef Kernel::Segment_2                                   Segment_2;
    typedef CGAL::Arrangement_2<CGAL::Arr_segment_traits_2<Kernel>> Arrangement;

    // Create an empty arrangement
    Arrangement arr;

    // Convert input segments to CGAL segments and insert them
    for (const auto& seg : segments) {
        Point_2 p1(seg.p1().x(), seg.p1().y());
        Point_2 p2(seg.p2().x(), seg.p2().y());
        Segment_2 cgal_seg(p1, p2);
        CGAL::insert(arr, cgal_seg);
    }

    return arr;
```

